import {
  ChangeDetectionStrategy,
  Component,
  inject,
  signal,
  computed
} from '@angular/core';
import { CustomService } from '@clinicaloffice/mpage-developer';
import { JsonPipe } from '@angular/common';
import { FormsModule } from '@angular/forms';

/**
 * Request configuration for CCL test scripts
 */
interface RequestConfig {
  id: string;
  name: string;
  scriptName: string;
  description: string;
  defaultParams: Record<string, string>;
}

/**
 * History item for tracking executed requests
 */
interface HistoryItem {
  id: string;
  timestamp: Date;
  configId: string;
  params: Record<string, string>;
  response: any;
  error: string | null;
  elapsed: number;
}

/**
 * CCL Test Component for Blood Bank Validator
 *
 * Provides a testing interface for:
 * - mrha_bb_val_list_dir - List files in extract directory
 * - mrha_bb_val_read_file - Read file content
 * - gbin_mpage_template - Basic template test
 *
 * Based on Clinical Office testing patterns from gbin-mha-pds
 */
@Component({
  selector: 'app-ccl-test',
  imports: [JsonPipe, FormsModule],
  templateUrl: './ccl-test.html',
  styleUrl: './ccl-test.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CclTest {
  private customService = inject(CustomService);

  // Available request configurations
  readonly REQUEST_CONFIGS: RequestConfig[] = [
    {
      id: 'listDir',
      name: 'List Directory (mrha_bb_val_list_dir)',
      scriptName: 'mrha_bb_val_list_dir:group1',
      description: 'Lists .txt files in the specified directory. Uses dcl() with platform-specific ls/dir commands.',
      defaultParams: {
        directory: 'cclscratch:',
        filemask: '*.txt'
      }
    },
    {
      id: 'readFile',
      name: 'Read File (mrha_bb_val_read_file)',
      scriptName: 'mrha_bb_val_read_file:group1',
      description: 'Reads content of a specific file from the directory.',
      defaultParams: {
        directory: 'cclscratch:',
        filename: ''
      }
    },
    {
      id: 'templateTest',
      name: 'Template Test (gbin_mpage_template)',
      scriptName: 'gbin_mpage_template:group1',
      description: 'Basic Clinical Office template test script. Returns server info and timestamp.',
      defaultParams: {}
    }
  ];

  // State signals
  selectedConfigId = signal<string>('listDir');
  params = signal<Record<string, string>>({});
  loading = signal(false);
  results = signal<any>(null);
  error = signal<string | null>(null);
  history = signal<HistoryItem[]>([]);
  showHistory = signal(false);

  // Computed values
  selectedConfig = computed(() =>
    this.REQUEST_CONFIGS.find(c => c.id === this.selectedConfigId())
  );

  formattedResults = computed(() => {
    const r = this.results();
    return r ? JSON.stringify(r, null, 2) : '';
  });

  constructor() {
    // Initialize params with default values
    this.resetParams();
  }

  /**
   * Handle config selection change
   */
  onConfigChange(): void {
    this.resetParams();
    this.clearResults();
  }

  /**
   * Reset params to defaults for current config
   */
  resetParams(): void {
    const config = this.selectedConfig();
    if (config) {
      this.params.set({ ...config.defaultParams });
    }
  }

  /**
   * Update a parameter value
   */
  updateParam(key: string, value: string): void {
    this.params.update(p => ({ ...p, [key]: value }));
  }

  /**
   * Execute the selected CCL script
   */
  executeScript(): void {
    const config = this.selectedConfig();
    if (!config) {
      this.error.set('No script configuration selected');
      return;
    }

    this.loading.set(true);
    this.error.set(null);
    this.results.set(null);

    const startTime = Date.now();
    const currentParams = this.params();

    // Execute the custom CCL script
    this.customService.load(
      {
        customScript: {
          script: [
            {
              name: config.scriptName,
              run: 'pre',
              id: config.id,
              reference: true,
              parameters: currentParams
            }
          ],
          clearPatientSource: true
        }
      },
      [{ personId: 0, encntrId: 0 }],
      () => {
        const elapsed = Date.now() - startTime;
        const response = this.customService.get(config.id);

        const historyItem: HistoryItem = {
          id: crypto.randomUUID(),
          timestamp: new Date(),
          configId: config.id,
          params: { ...currentParams },
          response: response,
          error: null,
          elapsed
        };

        if (response) {
          if (response.error) {
            this.error.set(response.error);
            historyItem.error = response.error;
          } else {
            this.results.set(response);
          }
        } else {
          const errMsg = 'No response from CCL script';
          this.error.set(errMsg);
          historyItem.error = errMsg;
        }

        // Add to history
        this.history.update(h => [historyItem, ...h.slice(0, 19)]);

        this.loading.set(false);
      }
    );
  }

  /**
   * Clear the results
   */
  clearResults(): void {
    this.results.set(null);
    this.error.set(null);
  }

  /**
   * Clear history
   */
  clearHistory(): void {
    this.history.set([]);
  }

  /**
   * Load a history item
   */
  loadHistoryItem(item: HistoryItem): void {
    this.selectedConfigId.set(item.configId);
    this.params.set({ ...item.params });
    this.results.set(item.response);
    this.error.set(item.error);
    this.showHistory.set(false);
  }

  /**
   * Toggle history panel
   */
  toggleHistory(): void {
    this.showHistory.update(v => !v);
  }

  /**
   * Get parameter keys for current config
   */
  getParamKeys(): string[] {
    return Object.keys(this.params());
  }

  /**
   * Format timestamp for display
   */
  formatTime(date: Date): string {
    return date.toLocaleTimeString();
  }

  /**
   * Copy results to clipboard
   */
  copyResults(): void {
    const text = this.formattedResults();
    if (text) {
      navigator.clipboard.writeText(text);
    }
  }

  /**
   * Get the payload that will be sent (for debugging)
   */
  getPayloadPreview(): string {
    const config = this.selectedConfig();
    if (!config) return '';

    const payload = {
      payload: {
        patientSource: [{ personId: 0, encntrId: 0 }],
        customScript: {
          script: [{
            name: config.scriptName,
            run: 'pre',
            id: config.id,
            parameters: this.params()
          }],
          clearPatientSource: true
        }
      }
    };

    return JSON.stringify(payload, null, 2);
  }
}
